using System;using System.Drawing;using System.Linq;using System.Reflection;using System.Threading;using System.Windows.Forms;
namespace Frociart.Tests {
 sealed class PolishCanvas:FlowCanvas {protected override Keys GetInteractionModifiers(){return Keys.None;}protected override void OnLostFocus(EventArgs e){}protected override void OnMouseCaptureChanged(EventArgs e){}internal void Down(Point p){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));Capture=false;}internal void MoveTo(Point p,bool left=false){OnMouseMove(new MouseEventArgs(left?MouseButtons.Left:MouseButtons.None,0,p.X,p.Y,0));}internal void Up(Point p){OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));}internal void LeaveCanvas(){OnMouseLeave(EventArgs.Empty);}}
 sealed class PolishHost:Form {protected override bool ShowWithoutActivation{get{return true;}}}
 static class PointerPolishTests {
 static int checks;static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 static void Check(bool b,string text){if(!b)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
 static object Get(object o,string n){for(Type t=o.GetType();t!=null;t=t.BaseType){var f=t.GetField(n,F);if(f!=null)return f.GetValue(o);}throw new Exception(n);}
 static object Call(object o,string n,params object[] args){for(Type t=o.GetType();t!=null;t=t.BaseType){var m=t.GetMethod(n,F);if(m!=null)return m.Invoke(o,args);}throw new Exception(n);}
 static Bitmap Frame(FlowCanvas c){var image=new Bitmap(c.Width,c.Height);c.DrawToBitmap(image,c.ClientRectangle);return image;}
 static bool Different(Bitmap a,Bitmap b,Point p){for(int y=Math.Max(0,p.Y-15);y<Math.Min(a.Height,p.Y+15);y++)for(int x=Math.Max(0,p.X-15);x<Math.Min(a.Width,p.X+15);x++)if(a.GetPixel(x,y)!=b.GetPixel(x,y))return true;return false;}
 static void Pump(int ms){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(2);}while(DateTime.UtcNow<end);}
 static Point PointAt(FlowCanvas c,FlowNode n,bool port=false,bool right=false){var b=FlowCanvas.GetNodeBounds(n);return Point.Round(c.WorldToClient(n.Kind==NodeKind.Decision&&port?new PointF(right?b.Right:b.Left,b.Top+b.Height/2):new PointF(b.X+b.Width/2,port?b.Bottom:b.Y+b.Height/2)));}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();UiMotion.SetEnabled(true);Ui.SetDarkMode(true,false);using(var host=new PolishHost{ClientSize=new Size(1000,800),Location=new Point(-4000,-3000),StartPosition=FormStartPosition.Manual,ShowInTaskbar=false})using(var c=new PolishCanvas{Dock=DockStyle.Fill}){host.Controls.Add(c);host.Show();c.Diagram=Examples.Parity();c.SnapToGrid=false;c.FitToView();Pump(100);var n=c.Diagram.Nodes.First(x=>x.Kind==NodeKind.Input);int changed=0;c.DiagramChanged+=(s,e)=>changed++;c.SelectNode(null);
 var center=PointAt(c,n);c.MoveTo(center);Pump(20);using(var mid=Frame(c)){Pump(220);using(var end=Frame(c))Check(Different(mid,end,PointAt(c,n,true)),"Hover reveal paints intermediate port pixels through the retained canvas cache");}Check((string)Get(c,"_hoverNodeId")==n.Id&&c.SelectedNodeId==null,"Hover reveals affordance without selecting the block");var motions=(System.Collections.IDictionary)Get(c,"hoverPorts");Check(motions.Contains(n.Id),"Hover starts a finite port reveal animation");Pump(220);var port=PointAt(c,n,true);c.MoveTo(new Point(port.X,port.Y+5));Check((string)Get(c,"_hoverNodeId")==n.Id&&c.Cursor==Cursors.Cross,"Plus remains reachable across the block boundary");Check(changed==0,"Hover creates no document change");c.Down(port);c.Up(port);Check(c.IsConnecting||c.IsBlockPickerOpen,"Hover plus is clickable before any selection");Call(c,"CancelBlockPicker");c.CancelConnection();c.SelectNode(null);
 var decision=c.Diagram.Nodes.First(x=>x.Kind==NodeKind.Decision);c.MoveTo(PointAt(c,decision));Pump(220);Check(Call(c,"HitPort",decision,c.ClientToWorld(PointAt(c,decision,true))).Equals("true")&&Call(c,"HitPort",decision,c.ClientToWorld(PointAt(c,decision,true,true))).Equals("false"),"Both colored decision ports remain distinct on hover");c.MoveTo(new Point(5,5));Pump(240);Check(((System.Collections.IDictionary)Get(c,"hoverPorts")).Count==0&&!((System.Windows.Forms.Timer)Get(c,"manipulationTimer")).Enabled,"Leaving hover removes its visual and stops its timer");
 c.MoveTo(center);c.Down(center);var release=new Point(center.X+180,center.Y+95);c.MoveTo(release,true);c.Up(release);Check((float)Get(c,"landingLift")==0&&!(bool)Get(c,"landingPeeled"),"Ordinary drag release never starts the sticker lift or fold");Check((float)Get(c,"landingPulse")==0,"Ordinary landing begins at the exact release pose");Pump(70);Check(Math.Abs((float)Get(c,"landingPulse"))>.005,"Ordinary release has a small elastic intermediate frame");Pump(400);Check((string)Get(c,"landingId")==null&&(float)Get(c,"landingLift")==0,"Release settles and clears its animation state");c.ViewOnly=true;c.MoveTo(center);Check(!(bool)Call(c,"ShowsPorts",n),"Read-only canvas does not expose editable hover controls");host.Close();}
 using(var bitmap=new Bitmap(260,180)){using(var g=Graphics.FromImage(bitmap))g.Clear(Ui.Surface);using(var fade=new PopupGhost((Bitmap)bitmap.Clone(),new Rectangle(-4000,-3000,260,180),.7)){fade.Show();Check(fade.SurfaceReady&&fade.CurrentAlpha==178,"Fade surface is fully uploaded before the popup becomes visible");Pump(55);Check(fade.CurrentAlpha>0&&fade.CurrentAlpha<178,"Closing menu fades through real intermediate opacity");Pump(180);Check(PopupGhost.ActiveCount==0,"Fade disposes its native window and resources");}}
 Console.WriteLine("POINTER_POLISH_FINISHED checks="+checks+" errors=0");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 }
}

